INSERT OR IGNORE INTO content_translations(entity_type,entity_id,locale,value,source_revision,actor) SELECT 'workshop',id,'es-MX','{"name": "Jardín de papel — ejemplo de vista previa", "summary": "Ejemplo ficticio de creación con papel para revisar el sitio. No es una clase disponible.", "description": "Solo es una muestra de diseño. Explora figuras de papel, hojas en capas y la composición de un jardín. Esta descripción ficticia sirve para revisar la interfaz; no anuncia una actividad de Adventure Station. No hay inscripciones ni pagos disponibles.", "category": "Ejemplo de vista previa", "materials": "Materiales de ejemplo: papel, crayones y pegamento.", "instructions": "Instrucciones ficticias. No asistas ni viajes a esta ubicación."}',revision,'system:synthetic-preview' FROM workshops WHERE id='preview-paper';
INSERT OR IGNORE INTO content_translations(entity_type,entity_id,locale,value,source_revision,actor) SELECT 'workshop',id,'es-MX','{"name": "Pintura y patrones — ejemplo de vista previa", "summary": "Ejemplo ficticio de pintura. No hay una sesión real ni pagos disponibles.", "description": "Solo es una muestra de diseño. Esta descripción permite revisar la comodidad de lectura, los saltos de línea y la relación entre edades, materiales, fechas y precio. No es un taller anunciado por Adventure Station.", "category": "Ejemplo de vista previa", "materials": "Materiales de ejemplo: papel, crayones y pegamento.", "instructions": "Instrucciones ficticias. No asistas ni viajes a esta ubicación."}',revision,'system:synthetic-preview' FROM workshops WHERE id='preview-paint';
INSERT OR IGNORE INTO content_translations(entity_type,entity_id,locale,value,source_revision,actor) SELECT 'workshop',id,'es-MX','{"name": "Pequeños mundos — ejemplo de vista previa", "summary": "Ejemplo ficticio de collage para revisar el diseño; no es una actividad disponible.", "description": "Solo es una muestra de diseño. Revisa otro rango de edad y precio sin presentar esto como una clase real. Las inscripciones no están abiertas.", "category": "Ejemplo de vista previa", "materials": "Materiales de ejemplo: papel, crayones y pegamento.", "instructions": "Instrucciones ficticias. No asistas ni viajes a esta ubicación."}',revision,'system:synthetic-preview' FROM workshops WHERE id='preview-collage';
INSERT OR IGNORE INTO content_translations(entity_type,entity_id,locale,value,source_revision,actor) SELECT 'venue',id,'es-MX','{"instructions": "Instrucciones de llegada de ejemplo. No viajes a esta ubicación.", "accessibility": "Información ficticia de accesibilidad para revisar la interfaz."}',revision,'system:synthetic-preview' FROM venues WHERE id='preview-location';
